const assets='assets/robot-original/',views=[['overview','管控总览','overview.png'],['monitor','巡检监控','monitor.png'],['scenes','场景列表','scenes.png'],['deployment','场景部署','deployment.png'],['control','场景控制','control.png'],['configuration','控制配置','configuration.png'],['login','登录','login.jpeg']],q=new URLSearchParams(location.search),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let view=views.some(v=>v[0]===q.get('view'))?q.get('view'):'overview',playing=false,still=q.get('still')==='1',animation=null,loaded=false;
if(q.get('embed')==='1')document.body.classList.add('hide-controls');const wrap=document.createElement('div');wrap.className='original-wrap';document.body.append(wrap);const controls=document.createElement('div');controls.className='original-controls';document.body.append(controls);
const frames=[{transform:'perspective(1100px) translateY(0px) rotateY(0deg) rotateZ(0deg)',offset:0},{transform:'perspective(1100px) translateY(-7px) rotateY(20deg) rotateZ(1.8deg)',offset:.25},{transform:'perspective(1100px) translateY(0px) rotateY(0deg) rotateZ(0deg)',offset:.5},{transform:'perspective(1100px) translateY(-7px) rotateY(-20deg) rotateZ(-1.8deg)',offset:.75},{transform:'perspective(1100px) translateY(0px) rotateY(0deg) rotateZ(0deg)',offset:1}];
function fit(){const ch=document.body.classList.contains('hide-controls')?0:controls.getBoundingClientRect().height,s=Math.min(innerWidth/1920,(innerHeight-ch)/1080);wrap.style.width=1920*s+'px';wrap.style.height=1080*s+'px';document.querySelector('.original-canvas').style.transform=`scale(${s})`}
function notify(){const s={type:'robot-original-motion-state',view,playing,still,ready:loaded,reduced};if(parent!==window)parent.postMessage(s,location.origin);const b=controls.querySelector('[data-action=motion]');if(b)b.textContent=view!=='overview'?'播放总览动效':playing?'暂停动效':'播放动效'}
async function render(){animation?.cancel();animation=null;loaded=false;const v=views.find(v=>v[0]===view);wrap.innerHTML=`<div class="original-canvas"><img class="original-image" src="${assets+v[2]}" width="1920" height="1080" alt="${v[1]}原设计稿">${view==='overview'&&!still?'<div class="original-patch"><img src="'+assets+'background.png" alt=""></div><img class="original-core" src="'+assets+'core-alpha.png" alt="原稿中央主视觉动效层"><img class="original-satellites" src="'+assets+'satellites-alpha.png" alt="原稿周边机器人图层">':''}</div>`;
controls.innerHTML=`<nav class="original-tabs" aria-label="原设计稿页面">${views.map(v=>`<button data-view="${v[0]}" role="tab" aria-selected="${v[0]===view}">${v[1]}</button>`).join('')}</nav><div class="original-actions"><span>${view==='overview'?'原主视觉摆转动效 · 其他区域保持静止':'当前为静态原稿'}</span><button data-action="motion">播放动效</button><button data-action="original">${still?'查看动效':'查看静态原稿'}</button><button data-action="full">全屏</button><a href="robot.html">返回案例 ↗</a></div>`;fit();history.replaceState({},'',`?view=${view}${q.get('embed')==='1'?'&embed=1':''}${still?'&still=1':''}`);
const core=document.querySelector('.original-core');if(core){animation=core.animate(frames,{duration:8000,iterations:Infinity,easing:'ease-in-out',fill:'both'});animation.pause();animation.currentTime=0;if(playing)animation.play()}await Promise.allSettled([...wrap.querySelectorAll('img')].map(i=>i.decode()));loaded=true;notify()}
async function play(){if(view!=='overview'||still){view='overview';still=false;playing=true;await render()}else{playing=true;animation?.play();notify()}}function pause(){playing=false;animation?.pause();notify()}async function toggle(){if(playing&&view==='overview'&&!still)pause();else await play()}
controls.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){pause();view=b.dataset.view;await render();return}if(b.dataset.action==='motion')await toggle();if(b.dataset.action==='original'){if(still)await play();else{pause();still=true;await render()}}if(b.dataset.action==='full'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{b.textContent='请在独立窗口查看'}}});
addEventListener('message',async e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='robot-original-motion-command')return;if(e.data.action==='play')await play();else if(e.data.action==='pause')pause();else if(e.data.action==='toggle')await toggle();else if(e.data.action==='state')notify()});addEventListener('resize',fit);window.OriginalRobot={async setView(v){if(views.some(x=>x[0]===v)){pause();view=v;await render()}},play,pause,toggle,get view(){return view},get playing(){return playing},get still(){return still},get animation(){return animation},get ready(){return loaded}};render().then(()=>{if(!still&&!reduced&&q.get('autoplay')!=='0')play()});
